/**
 * FILE: p2p-kids-marketplace/src/services/notificationAnalytics.ts
 * MODULE: MODULE-14-NOTIFICATIONS-V2 (NOTIF-V2-010)
 * TASK: Notification Analytics & Metrics
 * 
 * Service for tracking notification events (delivery, open, click, failure)
 * and integrating with Expo Notifications for analytics
 */

import { supabase } from '@/config/supabase';
import * as Notifications from 'expo-notifications';

export interface NotificationEvent {
  notification_id: string;
  event_type: 'delivered' | 'opened' | 'clicked' | 'failed';
  event_data?: Record<string, any>;
}

export class NotificationAnalyticsService {
  private static initialized = false;

  /**
   * Track notification delivered event
   */
  static async trackDelivered(notificationId: string): Promise<void> {
    try {
      const { error } = await supabase.rpc('track_notification_event', {
        p_notification_id: notificationId,
        p_event_type: 'delivered',
        p_event_data: {
          timestamp: new Date().toISOString(),
        },
      });

      if (error) {
        console.error('[NotificationAnalytics] trackDelivered error:', error);
      }
    } catch (err) {
      console.error('[NotificationAnalytics] trackDelivered exception:', err);
    }
  }

  /**
   * Track notification opened event
   */
  static async trackOpened(notificationId: string): Promise<void> {
    try {
      const { error } = await supabase.rpc('track_notification_event', {
        p_notification_id: notificationId,
        p_event_type: 'opened',
        p_event_data: {
          timestamp: new Date().toISOString(),
        },
      });

      if (error) {
        console.error('[NotificationAnalytics] trackOpened error:', error);
      }
    } catch (err) {
      console.error('[NotificationAnalytics] trackOpened exception:', err);
    }
  }

  /**
   * Track notification clicked event (deep link followed)
   */
  static async trackClicked(
    notificationId: string,
    deepLink: string
  ): Promise<void> {
    try {
      const { error } = await supabase.rpc('track_notification_event', {
        p_notification_id: notificationId,
        p_event_type: 'clicked',
        p_event_data: {
          deep_link: deepLink,
          timestamp: new Date().toISOString(),
        },
      });

      if (error) {
        console.error('[NotificationAnalytics] trackClicked error:', error);
      }
    } catch (err) {
      console.error('[NotificationAnalytics] trackClicked exception:', err);
    }
  }

  /**
   * Track notification failure event
   */
  static async trackFailed(
    notificationId: string,
    errorMessage: string
  ): Promise<void> {
    try {
      const { error } = await supabase.rpc('track_notification_event', {
        p_notification_id: notificationId,
        p_event_type: 'failed',
        p_event_data: {
          error: errorMessage,
          timestamp: new Date().toISOString(),
        },
      });

      if (error) {
        console.error('[NotificationAnalytics] trackFailed error:', error);
      }
    } catch (err) {
      console.error('[NotificationAnalytics] trackFailed exception:', err);
    }
  }

  /**
   * Initialize analytics tracking listeners
   * Call this once in App.tsx or main entry point
   */
  static initialize(): void {
    if (this.initialized) {
      console.warn('[NotificationAnalytics] Already initialized, skipping');
      return;
    }

    console.log('[NotificationAnalytics] Initializing analytics tracking...');

    // Track notification opens and clicks
    Notifications.addNotificationResponseReceivedListener((response) => {
      const notificationData = response.notification.request.content.data;
      const notificationId = notificationData?.notification_id as string | undefined;

      if (!notificationId) {
        console.warn('[NotificationAnalytics] No notification_id in response data');
        return;
      }

      console.log('[NotificationAnalytics] Notification interaction detected:', {
        notificationId,
        actionIdentifier: response.actionIdentifier,
      });

      // Track opened
      this.trackOpened(notificationId);

      // Track click if deep link present
      const deepLink = notificationData?.deep_link as string | undefined;
      if (deepLink) {
        console.log('[NotificationAnalytics] Deep link detected:', deepLink);
        this.trackClicked(notificationId, deepLink);
      }
    });

    // Track notification received while app is foregrounded
    Notifications.addNotificationReceivedListener((notification) => {
      const notificationData = notification.request.content.data;
      const notificationId = notificationData?.notification_id as string | undefined;

      if (notificationId) {
        console.log('[NotificationAnalytics] Notification received (foreground):', notificationId);
        this.trackDelivered(notificationId);
      }
    });

    this.initialized = true;
    console.log('[NotificationAnalytics] Analytics tracking initialized');
  }

  /**
   * Get analytics for a specific date range (for admin dashboard)
   */
  static async getAnalytics(
    startDate: Date,
    endDate: Date,
    category?: string
  ): Promise<any> {
    try {
      const { data, error } = await supabase.rpc('get_notification_analytics', {
        p_start_date: startDate.toISOString(),
        p_end_date: endDate.toISOString(),
        p_category: category || null,
      });

      if (error) {
        console.error('[NotificationAnalytics] getAnalytics error:', error);
        return null;
      }

      return data;
    } catch (err) {
      console.error('[NotificationAnalytics] getAnalytics exception:', err);
      return null;
    }
  }

  /**
   * Get A/B test performance for a specific notification type
   */
  static async getABTestPerformance(
    notificationType: string,
    startDate: Date,
    endDate: Date
  ): Promise<any> {
    try {
      const { data, error } = await supabase.rpc('get_ab_test_performance', {
        p_notification_type: notificationType,
        p_start_date: startDate.toISOString(),
        p_end_date: endDate.toISOString(),
      });

      if (error) {
        console.error('[NotificationAnalytics] getABTestPerformance error:', error);
        return null;
      }

      return data;
    } catch (err) {
      console.error('[NotificationAnalytics] getABTestPerformance exception:', err);
      return null;
    }
  }
}

/**
 * FILE: p2p-kids-admin/src/app/analytics/notifications/page.tsx
 * MODULE: MODULE-14-NOTIFICATIONS-V2 (NOTIF-V2-010)
 * TASK: Notification Analytics & Metrics Dashboard
 * 
 * Admin dashboard for viewing notification analytics metrics:
 * - Delivery rates by category
 * - Open rates by type
 * - Click rates
 * - A/B test performance
 */

'use client';

import React, { useEffect, useState } from 'react';
import { createClientComponentClient } from '@supabase/auth-helpers-nextjs';

interface CategoryMetrics {
  category: string;
  variant: string;
  total: number;
  delivered: number;
  failed: number;
  opened: number;
  clicked: number;
  delivery_rate: number;
  open_rate: number;
  click_rate: number;
}

interface TypeMetrics {
  type: string;
  variant: string;
  total: number;
  delivered: number;
  opened: number;
  clicked: number;
  delivery_rate: number;
  open_rate: number;
  click_rate: number;
}

interface NotificationMetrics {
  total_sent: number;
  date_range: {
    start: string;
    end: string;
  };
  by_category: CategoryMetrics[];
  by_type: TypeMetrics[];
}

export default function NotificationAnalyticsPage() {
  const [metrics, setMetrics] = useState<NotificationMetrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [dateRange, setDateRange] = useState(30); // days
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const supabase = createClientComponentClient();

  useEffect(() => {
    loadMetrics();
  }, [dateRange, selectedCategory]);

  const loadMetrics = async () => {
    setLoading(true);
    setError(null);

    try {
      const startDate = new Date();
      startDate.setDate(startDate.getDate() - dateRange);

      const { data, error: rpcError } = await supabase.rpc(
        'get_notification_analytics',
        {
          p_start_date: startDate.toISOString(),
          p_end_date: new Date().toISOString(),
          p_category: selectedCategory,
        }
      );

      if (rpcError) {
        console.error('[NotificationAnalytics] RPC error:', rpcError);
        setError(rpcError.message);
      } else if (data) {
        setMetrics(data);
      }
    } catch (err) {
      console.error('[NotificationAnalytics] Load error:', err);
      setError('Failed to load analytics');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="p-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-1/4 mb-4"></div>
          <div className="h-32 bg-gray-200 rounded mb-4"></div>
          <div className="h-64 bg-gray-200 rounded"></div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-8">
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <h2 className="text-red-800 font-semibold">Error Loading Analytics</h2>
          <p className="text-red-600">{error}</p>
          <button
            onClick={() => loadMetrics()}
            className="mt-4 px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700"
          >
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="p-8 max-w-7xl mx-auto">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-2">Notification Analytics</h1>
        <p className="text-gray-600">
          Track delivery rates, open rates, and click rates for all notifications
        </p>
      </div>

      {/* Filters */}
      <div className="mb-6 flex gap-4 items-center">
        <div className="flex gap-2">
          <button
            onClick={() => setDateRange(7)}
            className={`px-4 py-2 rounded-lg transition ${
              dateRange === 7
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
            data-testid="date-range-7"
          >
            Last 7 Days
          </button>
          <button
            onClick={() => setDateRange(30)}
            className={`px-4 py-2 rounded-lg transition ${
              dateRange === 30
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
            data-testid="date-range-30"
          >
            Last 30 Days
          </button>
          <button
            onClick={() => setDateRange(90)}
            className={`px-4 py-2 rounded-lg transition ${
              dateRange === 90
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
            data-testid="date-range-90"
          >
            Last 90 Days
          </button>
        </div>

        <div>
          <label className="text-sm text-gray-600 mr-2">Category:</label>
          <select
            value={selectedCategory || ''}
            onChange={(e) => setSelectedCategory(e.target.value || null)}
            className="px-4 py-2 border border-gray-300 rounded-lg"
            data-testid="category-filter"
          >
            <option value="">All Categories</option>
            <option value="subscription">Subscription</option>
            <option value="sp_events">SP Events</option>
            <option value="badges">Badges</option>
            <option value="trades">Trades</option>
            <option value="system">System</option>
          </select>
        </div>
      </div>

      {metrics && (
        <>
          {/* Overview Card */}
          <div className="bg-white rounded-lg shadow p-6 mb-6">
            <h2 className="text-xl font-semibold mb-4">Overview</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div>
                <div className="text-4xl font-bold text-blue-600" data-testid="total-sent">
                  {metrics.total_sent.toLocaleString()}
                </div>
                <div className="text-gray-600">Total Notifications Sent</div>
              </div>
              <div>
                <div className="text-4xl font-bold text-green-600" data-testid="avg-delivery-rate">
                  {metrics.by_category.length > 0
                    ? (
                        metrics.by_category.reduce(
                          (sum, cat) => sum + cat.delivery_rate,
                          0
                        ) / metrics.by_category.length
                      ).toFixed(1)
                    : 0}
                  %
                </div>
                <div className="text-gray-600">Avg Delivery Rate</div>
              </div>
              <div>
                <div className="text-4xl font-bold text-purple-600" data-testid="avg-open-rate">
                  {metrics.by_category.length > 0
                    ? (
                        metrics.by_category.reduce(
                          (sum, cat) => sum + (cat.open_rate || 0),
                          0
                        ) / metrics.by_category.length
                      ).toFixed(1)
                    : 0}
                  %
                </div>
                <div className="text-gray-600">Avg Open Rate</div>
              </div>
            </div>
          </div>

          {/* Metrics by Category */}
          <div className="bg-white rounded-lg shadow overflow-hidden mb-6">
            <div className="p-6 border-b border-gray-200">
              <h2 className="text-xl font-semibold">Metrics by Category</h2>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full" data-testid="category-metrics-table">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Category
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Variant
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Total
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Delivered
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Delivery Rate
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Open Rate
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Click Rate
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200 bg-white">
                  {metrics.by_category.map((cat, index) => (
                    <tr key={`${cat.category}-${cat.variant}-${index}`}>
                      <td className="px-6 py-4 whitespace-nowrap font-medium text-gray-900">
                        {cat.category}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {cat.variant}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {cat.total}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {cat.delivered}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <span
                          className={`font-semibold ${
                            cat.delivery_rate >= 90
                              ? 'text-green-600'
                              : cat.delivery_rate >= 70
                              ? 'text-yellow-600'
                              : 'text-red-600'
                          }`}
                        >
                          {cat.delivery_rate?.toFixed(1) || 0}%
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <span className="font-semibold text-purple-600">
                          {cat.open_rate?.toFixed(1) || 0}%
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm">
                        <span className="font-semibold text-blue-600">
                          {cat.click_rate?.toFixed(1) || 0}%
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Top Performing Notification Types */}
          <div className="bg-white rounded-lg shadow overflow-hidden">
            <div className="p-6 border-b border-gray-200">
              <h2 className="text-xl font-semibold">Top Performing Types</h2>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full" data-testid="type-metrics-table">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Type
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Variant
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Total
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Open Rate
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Click Rate
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200 bg-white">
                  {metrics.by_type.slice(0, 10).map((type, index) => (
                    <tr key={`${type.type}-${type.variant}-${index}`}>
                      <td className="px-6 py-4 whitespace-nowrap font-medium text-gray-900">
                        {type.type}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {type.variant}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {type.total}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-semibold text-purple-600">
                        {type.open_rate?.toFixed(1) || 0}%
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-semibold text-blue-600">
                        {type.click_rate?.toFixed(1) || 0}%
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

/**
 * FILE: p2p-kids-marketplace/src/__tests__/services/notificationAnalytics.test.ts
 * MODULE: MODULE-14-NOTIFICATIONS-V2 (NOTIF-V2-010)
 * TASK: Unit Tests for Notification Analytics Service
 */

import { NotificationAnalyticsService } from '@/services/notificationAnalytics';
import { supabase } from '@/config/supabase';
import * as Notifications from 'expo-notifications';

// Mock Supabase
jest.mock('@/config/supabase', () => ({
  supabase: {
    rpc: jest.fn(),
  },
}));

// Mock Expo Notifications
jest.mock('expo-notifications', () => ({
  addNotificationResponseReceivedListener: jest.fn(),
  addNotificationReceivedListener: jest.fn(),
}));

describe('NotificationAnalyticsService', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    // Reset initialized state
    (NotificationAnalyticsService as any).initialized = false;
  });

  describe('trackDelivered', () => {
    it('should track delivered event successfully', async () => {
      const mockNotificationId = '123e4567-e89b-12d3-a456-426614174000';

      (supabase.rpc as jest.Mock).mockResolvedValue({ data: { success: true }, error: null });

      await NotificationAnalyticsService.trackDelivered(mockNotificationId);

      expect(supabase.rpc).toHaveBeenCalledWith('track_notification_event', {
        p_notification_id: mockNotificationId,
        p_event_type: 'delivered',
        p_event_data: expect.objectContaining({
          timestamp: expect.any(String),
        }),
      });
    });

    it('should handle RPC errors gracefully', async () => {
      const consoleSpy = jest.spyOn(console, 'error').mockImplementation();
      (supabase.rpc as jest.Mock).mockResolvedValue({ 
        data: null, 
        error: { message: 'Database error' } 
      });

      await NotificationAnalyticsService.trackDelivered('test-id');

      expect(consoleSpy).toHaveBeenCalledWith(
        expect.stringContaining('trackDelivered error'),
        expect.any(Object)
      );

      consoleSpy.mockRestore();
    });
  });

  describe('trackOpened', () => {
    it('should track opened event successfully', async () => {
      const mockNotificationId = '123e4567-e89b-12d3-a456-426614174000';

      (supabase.rpc as jest.Mock).mockResolvedValue({ data: { success: true }, error: null });

      await NotificationAnalyticsService.trackOpened(mockNotificationId);

      expect(supabase.rpc).toHaveBeenCalledWith('track_notification_event', {
        p_notification_id: mockNotificationId,
        p_event_type: 'opened',
        p_event_data: expect.objectContaining({
          timestamp: expect.any(String),
        }),
      });
    });
  });

  describe('trackClicked', () => {
    it('should track clicked event with deep link', async () => {
      const mockNotificationId = '123e4567-e89b-12d3-a456-426614174000';
      const mockDeepLink = 'app://trade/123';

      (supabase.rpc as jest.Mock).mockResolvedValue({ data: { success: true }, error: null });

      await NotificationAnalyticsService.trackClicked(mockNotificationId, mockDeepLink);

      expect(supabase.rpc).toHaveBeenCalledWith('track_notification_event', {
        p_notification_id: mockNotificationId,
        p_event_type: 'clicked',
        p_event_data: expect.objectContaining({
          deep_link: mockDeepLink,
          timestamp: expect.any(String),
        }),
      });
    });
  });

  describe('trackFailed', () => {
    it('should track failed event with error message', async () => {
      const mockNotificationId = '123e4567-e89b-12d3-a456-426614174000';
      const mockError = 'Invalid push token';

      (supabase.rpc as jest.Mock).mockResolvedValue({ data: { success: true }, error: null });

      await NotificationAnalyticsService.trackFailed(mockNotificationId, mockError);

      expect(supabase.rpc).toHaveBeenCalledWith('track_notification_event', {
        p_notification_id: mockNotificationId,
        p_event_type: 'failed',
        p_event_data: expect.objectContaining({
          error: mockError,
          timestamp: expect.any(String),
        }),
      });
    });
  });

  describe('initialize', () => {
    it('should set up notification listeners', () => {
      NotificationAnalyticsService.initialize();

      expect(Notifications.addNotificationResponseReceivedListener).toHaveBeenCalledTimes(1);
      expect(Notifications.addNotificationReceivedListener).toHaveBeenCalledTimes(1);
      expect((NotificationAnalyticsService as any).initialized).toBe(true);
    });

    it('should not initialize twice', () => {
      const consoleSpy = jest.spyOn(console, 'warn').mockImplementation();

      NotificationAnalyticsService.initialize();
      NotificationAnalyticsService.initialize();

      expect(Notifications.addNotificationResponseReceivedListener).toHaveBeenCalledTimes(1);
      expect(consoleSpy).toHaveBeenCalledWith(
        expect.stringContaining('Already initialized')
      );

      consoleSpy.mockRestore();
    });

    it('should track opened and clicked when notification is tapped', async () => {
      const trackOpenedSpy = jest.spyOn(NotificationAnalyticsService, 'trackOpened').mockResolvedValue();
      const trackClickedSpy = jest.spyOn(NotificationAnalyticsService, 'trackClicked').mockResolvedValue();

      let responseListener: any;
      (Notifications.addNotificationResponseReceivedListener as jest.Mock).mockImplementation((listener) => {
        responseListener = listener;
      });

      NotificationAnalyticsService.initialize();

      // Simulate notification response
      const mockResponse = {
        notification: {
          request: {
            content: {
              data: {
                notification_id: 'test-notif-id',
                deep_link: 'app://trade/123',
              },
            },
          },
        },
        actionIdentifier: 'default',
      };

      responseListener(mockResponse);

      // Wait for async operations
      await new Promise((resolve) => setTimeout(resolve, 10));

      expect(trackOpenedSpy).toHaveBeenCalledWith('test-notif-id');
      expect(trackClickedSpy).toHaveBeenCalledWith('test-notif-id', 'app://trade/123');

      trackOpenedSpy.mockRestore();
      trackClickedSpy.mockRestore();
    });
  });

  describe('getAnalytics', () => {
    it('should fetch analytics data successfully', async () => {
      const mockAnalytics = {
        total_sent: 100,
        by_category: [],
        by_type: [],
      };

      (supabase.rpc as jest.Mock).mockResolvedValue({ data: mockAnalytics, error: null });

      const startDate = new Date('2026-01-01');
      const endDate = new Date('2026-01-31');

      const result = await NotificationAnalyticsService.getAnalytics(startDate, endDate, 'sp_events');

      expect(supabase.rpc).toHaveBeenCalledWith('get_notification_analytics', {
        p_start_date: startDate.toISOString(),
        p_end_date: endDate.toISOString(),
        p_category: 'sp_events',
      });
      expect(result).toEqual(mockAnalytics);
    });

    it('should handle null category parameter', async () => {
      (supabase.rpc as jest.Mock).mockResolvedValue({ data: {}, error: null });

      const startDate = new Date();
      const endDate = new Date();

      await NotificationAnalyticsService.getAnalytics(startDate, endDate);

