    });

    expect(data).toMatchObject({ success: false, error: 'Invalid event type' });
  });

  it('should calculate correct delivery and open rates', async () => {
    if (!process.env.RUN_SUPABASE_E2E) {
      console.log('Skipping: RUN_SUPABASE_E2E not set');
