interface CategoryMetrics {
  category: string;
  variant: string;
  total: number;
  delivered: number;
  failed: number;
  opened: number;
  clicked: number;
  delivery_rate: number;
  open_rate: number;
  click_rate: number;
}

interface TypeMetrics {
  type: string;
  variant: string;
  total: number;
  delivered: number;
  opened: number;
  clicked: number;
  delivery_rate: number;
  open_rate: number;
  click_rate: number;
}

interface NotificationMetrics {
